INSERT INTO questions (exam_id, type, category, question, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, year) VALUES
  ('pm', 'past', 'プロジェクトステークホルダマネジメント', 'JIS Q 21500:2018（プロジェクトマネジメントの手引）によれば、プロジェクトガバナンスを維持する責任は誰にあるか。', 'プロジェクトの管理面でプロジェクトマネージャを支援するプロジェクトマネジメントチーム', 'プロジェクトの計画から終結までのプロセスを指揮するプロジェクトマネージャ', 'プロジェクトの要求事項を明確にし、プロジェクトの成果を享受する顧客', 'プロジェクトを許可し、経営的決定を下すプロジェクトスポンサ、又は上級レベルでの指導を行うプロジェクト運営委員会', 'd', 'JIS Q 21500:2018では、プロジェクトガバナンスはプロジェクトスポンサや上級レベルの意思決定機関（プロジェクト運営委員会）が責任を持つと定義されています。プロジェクトマネージャは実行責任を持ちますが、ガバナンス（統治）責任は上位組織にあります。', 'medium', '令和7年度 秋期'),
  ('pm', 'past', 'プロジェクト統合マネジメント', 'JIS Q 21500:2018（プロジェクトマネジメントの手引）において、「変更要求」によって「管理のプロセス群」に作用し、その結果である「承認された変更」によって「管理のプロセス群」から作用されるプロセス群はどれか。', '計画のプロセス群', '実行のプロセス群', '終結のプロセス群', '立ち上げのプロセス群', 'b', '変更要求は実行のプロセス群から管理のプロセス群へ作用し、承認された変更が管理のプロセス群から実行のプロセス群へ作用します。変更管理は実行フェーズ中に発生します。', 'medium', '令和7年度 秋期'),
  ('pm', 'past', 'プロジェクト統合マネジメント', 'プロジェクトの成果を予測する際に用いる回帰分析の説明はどれか。', 'アウトプットとこれに対応した一連のインプット変数との関係について多数のデータを用いて分析し、統計学的関係を明らかにする。', '差異、欠陥、又はリスクを引き起こす根源的な理由を明らかにする。', 'ベースラインと実際のパフォーマンスについて、違いが生じた原因と、違いの度合いを判定する。', '予算、コスト、スケジュール、又はスコープのパラメータとベースラインとの差異を判定し、これに基づいて将来のある時点におけるパラメータのベースラインからの差異を予測する。', 'a', '回帰分析とは、アウトプット変数と複数のインプット変数の関係を統計学的に分析し、将来の結果を予測する手法です。イは根本原因分析、ウは差異分析、エはEVM（アーンドバリュー分析）の説明です。', 'medium', '令和7年度 秋期'),
  ('pm', 'past', 'プロジェクトスコープマネジメント', 'プロジェクトマネジメントにおいて、スコープクリープが発生する原因となり得る事例はどれか。', 'スコープの大幅な拡大が必要となったので、変更要求の承認を得た。', '設計中の機能を拡充するための軽微な変更要求と判断したので、コストや工数を見積もることなく、設計作業を推進した。', 'プロジェクト初期に定義した成果物及び作業を変更する必要はないが、作業工数の見積りが過小であった。', '変更要求によるスコープの拡大を変更管理委員会に諮ったが、承認されなかった。', 'b', 'スコープクリープとは、正式な変更管理プロセスを経ずにスコープが拡大していく現象です。「軽微」と判断して承認なしに変更を進めることがスコープクリープの典型的な原因です。アは適切な変更管理を経ており問題ありません。', 'medium', '令和7年度 秋期'),
  ('pm', 'past', 'プロジェクト資源マネジメント', 'ホーソン効果の、システム開発プロジェクトにおける例として、適切なものはどれか。', '開発サイクルごとの成果物のレビューで、ある開発チームの成果物がプロダクトオーナーに注目されたことによって、その開発チームの士気が上がり、その後の生産性が向上した。', '開発チーム別の進捗報告会で、遅れを報告したチームは優秀なチームだったので遅れは挽回可能であるという報告を信用したが、次の進捗報告で遅れが拡大した。', '結合テストで3件の誤りが検出され、そのうちの2件の誤りが同一のモジュールに起因していたので、残りの1件もそのモジュールに起因していると思い込んで調査したが、そのモジュールから誤りは検出できなかった。', '全ての利用者が満足するUIを開発するという達成困難な目標を開発チームに対して設定したので、開発チームの士気が下がり、その後の生産性が低下した。', 'a', 'ホーソン効果とは、人が注目・観察されていることを意識することで、生産性や行動が変化する現象です。プロダクトオーナーに注目されたことで士気が上がり生産性が向上した例がこれに該当します。', 'medium', '令和7年度 秋期'),
  ('pm', 'past', 'プロジェクトスケジュールマネジメント', 'プレシデンスダイアグラム法（PDM）において、終了-開始関係（リード2日）と開始-開始関係（ラグ3日）が設定された3つのアクティビティがある。全ての作業を完了するための所要日数は最少で何日か。（図中の各アクティビティの所要日数に基づいて計算する）', '10日', '12日', '14日', '16日', 'b', 'プレシデンスダイアグラム法では、リード（先行）とラグ（遅延）を考慮してクリティカルパスを計算します。終了-開始関係でリード2日は2日早く開始でき、開始-開始関係でラグ3日は3日後に開始できます。各パスの所要日数を計算し最長となるパスが答えです。', 'hard', '令和7年度 秋期'),
  ('pm', 'past', 'プロジェクトスケジュールマネジメント', '作業Cの終了が計画から2日遅れたプロジェクトにおいて、作業Iが作業Gの全てが完了していなくても開始できることが分かったのでファストトラッキングを適用して計画を変更した。計画変更後の総所要日数は当初計画と比べてどのように変化するか。', '4日減少する', '2日減少する', '1日増加する', '2日増加する', 'c', 'ファストトラッキングは本来順番に行う作業を並行して実施する手法です。作業Cの2日遅れをファストトラッキングで部分的に挽回できますが、完全には解消できず、結果として1日の増加となります。', 'hard', '令和7年度 秋期'),
  ('pm', 'past', 'プロジェクトスケジュールマネジメント', 'プロジェクトのスケジュール管理で使用する「クリティカルチェーン法」の実施例はどれか。', '限りある資源とプロジェクトの不確実性とに対応するために、合流バッファとプロジェクトバッファとを設ける。', 'クリティカルパス上の作業に、生産性を向上させるための開発ツールを導入する。', 'クリティカルパス上の作業に、要員を追加投入する。', 'クリティカルパス上の先行作業が終了する前に後続作業に着手し、双方の作業を並行して実施する。', 'a', 'クリティカルチェーン法の特徴は、資源の制約とプロジェクトの不確実性に対応するため、合流バッファ（支流の作業に設置）とプロジェクトバッファ（プロジェクト末尾に設置）を用いることです。イはクラッシング、ウもクラッシング、エはファストトラッキングの説明です。', 'medium', '令和7年度 秋期'),
  ('pm', 'past', 'プロジェクトコストマネジメント', 'COCOMOには、システム開発の工数を見積もる式の一つとして「開発工数 = 3.0 × (開発規模)^b」がある。この式を基に、開発規模と開発生産性（開発規模 ÷ 開発工数）の関係を正しく表したグラフはどれか。', '開発規模が増加するにつれて開発生産性が直線的に増加するグラフ', '開発規模が増加するにつれて開発生産性が直線的に減少するグラフ', '開発規模に関わらず開発生産性が一定のグラフ', '開発規模が増加するにつれて開発生産性が逓減（非線形に減少）するグラフ', 'd', 'COCOMOでは工数 = 3.0 × 規模^b（b>1）なので、開発生産性 = 規模 ÷ 工数 = 規模 ÷ (3.0 × 規模^b) = 1/(3.0 × 規模^(b-1))となります。bが1より大きい場合、規模が大きくなるほど生産性は逓減（非線形に減少）します。', 'hard', '令和7年度 秋期'),
  ('pm', 'past', 'プロジェクトリスクマネジメント', 'JIS Q 21500:2018（プロジェクトマネジメントの手引）によれば、プロセス「リスクの特定」及びプロセス「リスクの評価」は、どのプロセス群に属するか。', '管理', '計画', '実行', '終結', 'b', 'JIS Q 21500:2018では、「リスクの特定」と「リスクの評価」はいずれも計画のプロセス群に属します。リスク管理活動の多くはプロジェクト計画段階で行われます。管理プロセス群は進捗管理や課題管理などが中心です。', 'medium', '令和7年度 秋期'),
  ('pm', 'past', 'プロジェクトコミュニケーションマネジメント', 'プロジェクトのコミュニケーション計画において作成した「会議体の一覧」に、プロジェクト内定例報告会・顧客定例報告会・ステアリングコミッティが記載されている。5W1Hの指針に照らしたときに、不足している項目はどれか。', '会議室の利用料', '重要度', '主催者及び参加者', '成果物', 'c', '5W1H（What・Why・Who・When・Where・How）の観点で会議体一覧を確認すると、What（内容）・Why（目的）・When（頻度）・Where（場所）は記載されていますが、Who（主催者及び参加者）が不足しています。', 'medium', '令和7年度 秋期'),
  ('pm', 'past', 'プロジェクトコミュニケーションマネジメント', 'JIS Q 21500:2018（プロジェクトマネジメントの手引）によれば、プロセス「コミュニケーションの計画」の目的はどれか。', 'プロジェクトに影響されるか、又は影響を及ぼす個人、集団又は組織を明らかにし、その利害及び関係に関連する情報を文書化すること', 'プロジェクトのステークホルダに対し、要求した情報を利用可能にすること及び情報に対する予期せぬ具体的な要求に対応すること', 'プロジェクトのステークホルダのコミュニケーションニーズを確実に満足し、コミュニケーションの問題が発生したときにそれを解決すること', 'プロジェクトのステークホルダの情報及びコミュニケーションのニーズを決定すること', 'd', '「コミュニケーションの計画」プロセスの目的は、ステークホルダのコミュニケーションニーズ（情報の種類・形式・頻度など）を決定することです。アはステークホルダの特定、イは情報配布、ウはコミュニケーションのマネジメントの目的です。', 'medium', '令和7年度 秋期'),
  ('pm', 'past', 'プロジェクト品質マネジメント', 'アジャイル開発プロセスにおいて、Bill WakeがINVESTと呼ばれる六つの観点を用いて行うことはどれか。', '効率よくアクティビティ図を作成する。', 'コード化できるレベルまで詳細化されたデータフロー図を作成する。', '再利用しやすいソフトウェアパターンとなっているかどうかを評価する。', '質の高いユーザーストーリーとなっているかどうかを評価する。', 'd', 'INVESTはIndependent（独立）・Negotiable（交渉可能）・Valuable（価値がある）・Estimable（見積り可能）・Small（小さい）・Testable（テスト可能）の頭文字で、ユーザーストーリーの品質を評価するための観点です。', 'medium', '令和7年度 秋期'),
  ('pm', 'past', 'プロジェクト品質マネジメント', 'JIS X 9169:2021（ソフトウェアライフサイクルプロセス）によれば、テクニカルプロセスの一つである妥当性確認プロセスの目的はどれか。', 'システムがその利用中に、意図された運用環境で意図された用途を達成することで、そのビジネス又はミッションの目標及び利害関係者要件（要求事項）を満たすという客観的証拠を提供する。', 'システム又はシステム要素がその指定された要件（要求事項）及び特性を満たしていることの客観的な証拠を提供する。', '製品、サービス及びプロセスの品質について、効果的な管理を支援し、これらの品質を実証するために、これらに関する客観的なデータ及び情報を収集し、分析し、報告する。', '組織の品質管理プロセスのプロジェクトへの効果的な適用を確実なものにするよう支援する。', 'a', '妥当性確認（Validation）は「正しいシステムを作っているか」を確認するプロセスで、実際の運用環境でステークホルダの要件を満たすかを客観的に確認します。イは検証（Verification）で「システムを正しく作っているか」の確認です。', 'hard', '令和7年度 秋期'),
  ('pm', 'past', 'プロジェクト統合マネジメント', 'スクラムを適用している開発において、スプリントの途中で開発チームだけの判断で変更できるものはどれか。', 'スプリントゴール', 'スプリントバックログ', '品質', 'プロダクトバックログ', 'b', 'スクラムにおいて、スプリントバックログはスプリント中に開発チームが自律的に管理・変更できます。スプリントゴールはスプリント中に変更できません。プロダクトバックログはプロダクトオーナーが管理します。品質基準は組織が定め、チームが勝手に下げることはできません。', 'medium', '令和7年度 秋期'),
  ('pm', 'past', 'プロジェクト品質マネジメント', 'JIS X 33002:2017（プロセスアセスメント実施に対する要求事項）の説明として、適切なものはどれか。', '組織のプロセスを継続的に改善して品質を高めるための要求事項を規定している。', '組織プロセスの品質を客観的に診断するための要求事項を規定している。', 'プロジェクトの実施に重要で、かつ、影響を及ぼすプロジェクトマネジメントの概念及びプロセスに関する包括的な手引きを規定している。', '明確に定義された用語を使用し、ソフトウェアライフサイクルプロセスの共通枠組みを規定している。', 'b', 'JIS X 33002はプロセスアセスメント（組織のプロセス能力を客観的に評価・診断すること）の実施要求事項を定めた規格です。アは改善プロセス、ウはJIS Q 21500、エはJIS X 9126などの説明です。', 'medium', '令和7年度 秋期'),
  ('pm', 'past', 'プロジェクト品質マネジメント', 'バグトラッキングシステムの説明として、最も適切なものはどれか。', 'ソースコードを画面に表示しながら、プログラムの実行及び中断、変数の値の表示などの、バグの発見を支援する機能を提供する。', 'テストケース及びテストプログラムの開発を支援して、バグの発見を容易にする。', 'バグの数とソースプログラムの諸元から、品質管理のためのメトリクスを算定する。', '発見されたバグの内容、バグが発生したソフトウェアのバージョンなどを記録し、その修正計画や修正履歴を管理する。', 'd', 'バグトラッキングシステムは発見されたバグを記録・追跡・管理するシステムです。Redmineなどがその代表例です。アはデバッガ、イはテスト支援ツール、ウはメトリクス計算ツールの説明です。', 'easy', '令和7年度 秋期'),
  ('pm', 'past', 'プロジェクト調達マネジメント', 'ITサービスにおけるコンピュータシステムの利用に対する課金を逓減課金方式で行うときのグラフはどれか。', '利用量に比例して課金額が直線的に増加するグラフ', '利用量に関わらず課金額が一定のグラフ', '利用量が増加するにつれて単位当たりの課金額が減少し、課金増加率が逓減するグラフ', '利用量が少ないうちは課金額がゼロで、一定量を超えると急増するグラフ', 'c', '逓減課金方式とは、利用量が増えるほど単位当たりの料金が安くなる（課金の増加率が逓減する）方式です。大量利用者に割引を適用する料金体系で、グラフは上に凸の曲線になります。', 'medium', '令和7年度 秋期'),
  ('pm', 'past', 'プロジェクト統合マネジメント', 'プロジェクトマネジメントの進捗管理や課題管理だけでなく、サービスマネジメントのインシデント管理やサービス要求管理にも利用できる、次の特徴をもつOSSはどれか。【特徴】実施すべきタスクをチケットとして扱い、起票、調査、解決、クローズなどの状態を用いてタスクの進捗が管理できる。チケットを利用したワークフローが実現できる。', 'Jenkins', 'Redmine', 'Selenium', 'Zabbix', 'b', 'Redmineはチケット管理機能を中心とするOSSのプロジェクト管理ツールです。進捗管理・課題管理・インシデント管理など幅広い用途に使えます。JenkinsはCI/CDツール、SeleniumはWebテスト自動化ツール、ZabbixはIT監視ツールです。', 'easy', '令和7年度 秋期'),
  ('pm', 'past', 'プロジェクトスコープマネジメント', '利用者要件のうち、非機能要件項目はどれか。', '新しい業務の在り方や運用に関わる業務手順、入出力情報、組織、責任、権限、業務上の制約などの項目', '新しい業務の遂行に必要なアプリケーションシステムに関わる利用者の作業、システム機能の実現範囲、機能間の情報の流れなどの項目', '経営戦略や情報戦略に関わる経営上のニーズ、システム化・システム改善を必要とする業務上の課題、求められる成果・目標などの項目', 'システム基盤に関わる可用性、性能、拡張性、運用性、保守性、移行性などの項目', 'd', '非機能要件とは、システムの「何をするか」ではなく「どのように動くか」を規定する要件です。可用性・性能・拡張性・運用性・保守性・移行性などがこれに当たります。アは業務要件、イは機能要件、ウはビジネス要件の説明です。', 'easy', '令和7年度 秋期'),
  ('pm', 'past', 'プロジェクト調達マネジメント', '下請代金支払遅延等防止法の対象となる下請事業者から納品されたプログラムに、下請事業者側の事情を原因とする重大なバグが支払期日よりも前に発見され、プログラムの修正が必要となった。このとき、支払期日を改めて定めようとする場合、同法で認められている期間（60日）の起算日はどれか。', '当初のプログラムの検査が終了した日', '当初のプログラムを下請事業者に返却した日', '修正済プログラムが納品された日', '修正済プログラムの検査が終了した日', 'c', '下請代金支払遅延等防止法では、給付の受領日から60日以内に下請代金を支払う義務があります。修正が必要となった場合、修正済みの成果物が納品された日（再受領日）を起算日として新たに60日の期間が設定されます。', 'hard', '令和7年度 秋期'),
  ('pm', 'past', 'プロジェクトコミュニケーションマネジメント', '組織において、公益通報制度を運用する際に留意すべきこととして、適切なものはどれか。', '公益通報制度について、利用方法の教育を行うとともに周知徹底を図らなければならない。', '公益通報の受付窓口は、社内に設置しなければならない。', '公益通報の受付窓口は、従業員が所属する組織の長としなければならない。', '公益通報は、氏名を明らかにして行わなければならない。', 'a', '公益通報者保護法では、組織は公益通報制度の利用方法について従業員に教育・周知する義務があります。受付窓口は社外（弁護士や外部機関）でも可能で、匿名通報も認められています。組織の長を窓口にすることも不適切です。', 'medium', '令和7年度 秋期'),
  ('pm', 'past', 'プロジェクト統合マネジメント', '多要素認証疲労攻撃の例はどれか。', '顔認証で画面ロックを解除できるスマートフォンを攻撃者が不正に使い、所有者が疲労して寝ている隙にその寝顔を利用して画面ロックの解除を試みる。', '攻撃者の用意した偽サイトに利用者を誘導し、利用者のパスワード、電話番号など認証に関する複数の要素を不正に取得する。', '多要素認証を利用可能なシステムの利用者に、攻撃者が「システムへの多要素認証でのログインが必要です」という偽の電子メールを繰り返し送り付け、利用者がうっかりログインしてしまうのを待つ。', 'パスワード認証とスマートフォンへのプッシュ通知による認証を採用しているシステムにおいて、利用者がプッシュ通知の承認操作を行うまで、攻撃者が不正なログイン操作を繰り返す。', 'd', '多要素認証（MFA）疲労攻撃（MFA Fatigue Attack）は、攻撃者がプッシュ通知を大量に送り続け、利用者が通知に疲れて誤って承認してしまうことを狙った攻撃です。正規のMFAシステムを悪用するのが特徴です。', 'medium', '令和7年度 秋期'),
  ('pm', 'past', 'プロジェクトリスクマネジメント', '組織の日常的な業務活動に係るリスクであり、過失による誤入力、情報システムの障害、内部者の不正などによって損失が発生するリスクが当てはまるものはどれか。', 'オペレーショナルリスク', '固有リスク', '地政学的リスク', 'レピュテーションリスク', 'a', 'オペレーショナルリスクとは、業務プロセス・人・システム・外部事象における不備や失敗から生じる損失リスクです。誤入力・システム障害・不正などが該当します。金融庁やバーゼル規制でも重要な概念です。', 'easy', '令和7年度 秋期'),
  ('pm', 'past', 'プロジェクト統合マネジメント', '外部から侵入されたサーバ及びそのサーバに接続されていた記憶媒体を調査対象としてデジタルフォレンジックスを行うことになった。証拠として保全するものには、遠隔にあるログサーバのアクセスログ、インストール用CD、サーバのメモリ上の情報、ハードディスクのデータが含まれる。保全の順序として、揮発性の観点から最も適切なものはどれか。', 'メモリ上の情報 → ハードディスクのデータ → アクセスログ → インストール用CD', 'アクセスログ → メモリ上の情報 → ハードディスクのデータ → インストール用CD', 'インストール用CD → アクセスログ → ハードディスクのデータ → メモリ上の情報', 'メモリ上の情報 → ハードディスクのデータ → インストール用CD → アクセスログ', 'd', 'デジタルフォレンジックスでは揮発性の高いものから保全します。揮発性の順：メモリ上の情報（電源OFF時に消失）＞ハードディスク（削除されると消失）＞インストール用CD（変化しにくい）＞遠隔ログサーバのログ（最も消失リスクが低い）。', 'hard', '令和7年度 秋期');